import * as T from './three.module.js';
import {GARAGE,VEHICLES,ensureVehicles,buyVehicle,rechargeVehicle,loadVehicleContract,unloadVehicle,deliverVehicle,tractorWork,recoverVehicle,vehicleStep,exitPosition} from './vehicles.js?v=vehicles12';
import {ensureCounty,contractStatus} from './county-sim.js?v=county11';
import {createFarmVehicle} from './vehicle-models.js?v=vehicles12';
const esc=v=>String(v).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
export function installFarmVehicles({scene,state,save,modal,toast,player,keys,blocked,register,walk,isBusy,clearRoute,shadow,block,sign}){
 const actors=new Map();let active=null,motion={speed:0},saveClock=0,hudClock=0,working=0;
 const driveway=new T.Mesh(new T.BoxGeometry(16,.05,3.5),new T.MeshStandardMaterial({color:'#c1b48e',roughness:1}));driveway.position.set(-41,.24,24);driveway.receiveShadow=true;scene.add(driveway);
 const garage=new T.Group();garage.position.set(GARAGE.x,.2,GARAGE.z+7);scene.add(garage);
 for(const [w,h,d,color,x,y,z]of [[14,.3,8,'#8b9a88',0,4.3,0],[14,4,.25,'#b5bba7',0,2,-4],[.3,4,8,'#b5bba7',-7,2,0],[.3,4,8,'#b5bba7',7,2,0],[1,2,.5,'#6e9e8c',-4,1,3]]){const mesh=new T.Mesh(new T.BoxGeometry(w,h,d),new T.MeshStandardMaterial({color,roughness:.9}));mesh.position.set(x,y,z);garage.add(mesh);}
 block(GARAGE.x,GARAGE.z+7,14,8);sign('FARM GARAGE',GARAGE.x,6,GARAGE.z+7);register(garage,{kind:'vehicles',x:GARAGE.x,z:GARAGE.z+7,approach:{x:GARAGE.x,z:GARAGE.z-3}});
 function sync(){for(const [id,v]of Object.entries(ensureVehicles(state).owned)){if(!actors.has(id)){const actor=createFarmVehicle(id,VEHICLES[id].color);scene.add(actor.root);register(actor.root,{kind:'vehicles',vehicleId:id,x:v.x,z:v.z,approach:{x:v.x+3,z:v.z}});actors.set(id,actor);}const a=actors.get(id);a.root.position.set(v.x,.2,v.z);a.root.rotation.y=v.heading;a.update(0,0,v.cargo.length>0);}}
 sync();
 const driving=()=>active!==null;
 const near=v=>Math.hypot(v.x-player.position.x,v.z-player.position.z)<5;
 function hud(){const e=document.querySelector('#vehicle-hud');if(!e)return;e.hidden=!active;if(!active)return;const v=ensureVehicles(state).owned[active];document.querySelector('#vehicle-readout').textContent=VEHICLES[active].name+' · '+Math.round(v.energy)+'% · '+Math.round(Math.abs(motion.speed)*3.6)+' km/h';const work=document.querySelector('#tractor-work');if(work)work.hidden=active!=='tractor';}
 function apply(action,message){try{action();sync();save();toast(message);window.openVehicles(active||'tractor');}catch(e){toast(e.message);}}
 window.openVehicles=(selected=active||'tractor')=>{const owned=ensureVehicles(state).owned;let body='<span class="service-tag">FARM GARAGE</span><h2>Put your farm in gear.</h2><p>Your starter electric tractor is ready. The pickup carries village deliveries. Both use power from stores to recharge at the farm garage.</p>';
 for(const [id,spec]of Object.entries(VEHICLES)){const v=owned[id];body+='<article class="county-card"><h3>'+spec.name+'</h3><p>'+(id==='tractor'?'Field cultivator · faster North Fields production':'Delivery pickup · visible cargo bed')+(id==='tractor'?' · field implement': ' · '+spec.capacity+' cargo units')+'</p>'+(v?'<p>Battery '+Math.round(v.energy)+'% · Cargo '+v.cargo.reduce((n,c)=>n+c.quantity,0)+' / '+spec.capacity+' · Parked '+Math.round(v.x)+', '+Math.round(v.z)+'</p><div class="choice"><button class="primary" onclick="enterFarmVehicle(\''+id+'\')">'+(active===id?'Driving':'Walk over & drive')+'</button><button onclick="chargeFarmVehicle(\''+id+'\')">Charge +25% · 1 power</button><button onclick="unloadFarmVehicle(\''+id+'\')">Unload at garage</button><button onclick="recoverFarmVehicle(\''+id+'\')">Recover to garage · 2 power</button></div>'+v.cargo.map(c=>'<p>'+c.quantity+' '+esc(c.good)+' loaded <button onclick="deliverFarmVehicle(\''+id+'\',\''+c.contractId+'\')">Hand over at depot</button></p>').join('')+(id==='pickup'?'<details><summary>Load an accepted village request</summary>'+ensureCounty(state).contracts.filter(r=>contractStatus(state,r)==='active').map(r=>'<button onclick="loadFarmVehicle(\''+id+'\',\''+r.id+'\')">Load '+r.qty+' '+esc(r.good)+' · '+esc(r.buyer)+'</button>').join('')+'</details>':''):'<p>Purchase: '+spec.price+' farm coins</p><button class="primary" onclick="purchaseFarmVehicle(\''+id+'\')">Walk to garage & buy</button>')+'</article>';}
 modal(body+(active?'<button class="primary" onclick="exitFarmVehicle()">Park & get out</button>':'<button onclick="visitFarmGarage()">Walk to farm garage</button>')+'<button onclick="openCountyContracts()">Village requests</button><p>Drive with W/S or ↑/↓ for forward and reverse, A/D or ←/→ to steer. Space or Brake stops. Park before walking or using farm tasks. Drive inside owned North Fields and stop to plant or harvest with the tractor (5% charge); tractor planting takes one farm day with the normal seed and water costs.</p><p>Load and unload only while the vehicle is parked at the garage. Drive loaded requests to the depot at −72, −45 and hand them over before their deadline. No payment is made for loading. Vehicles and cargo are saved in this browser.</p>');};
 window.visitFarmGarage=()=>{if(active)return toast('Park and get out first.');document.querySelector('dialog').close();walk(GARAGE.x,GARAGE.z-3,'Walk to farm garage',()=>window.openVehicles());};
 window.purchaseFarmVehicle=id=>{if(active||isBusy())return toast('Park and finish your current tasks first.');document.querySelector('dialog').close();walk(GARAGE.x,GARAGE.z-3,'Buy '+(VEHICLES[id]?.name||'vehicle'),()=>apply(()=>buyVehicle(state,id),'Vehicle purchased.'));};
 function enter(id){const v=ensureVehicles(state).owned[id];if(!v||!near(v))return toast('Walk closer to your vehicle first.');clearRoute();active=id;motion.speed=0;for(const k in keys)keys[k]=false;player.visible=false;if(shadow)shadow.visible=false;player.position.set(v.x,.2,v.z);document.querySelector('dialog').close();hud();save();toast('Driving '+VEHICLES[id].name+'. Use arrows to drive and steer; Brake to stop.');}
 window.enterFarmVehicle=id=>{if(active)return toast('Park and get out before changing vehicles.');if(isBusy())return toast('Finish or clear your farm task queue first.');const v=ensureVehicles(state).owned[id];if(!v)return toast('Buy this vehicle first.');if(near(v))return enter(id);const p=exitPosition(v,blocked);if(!p)return toast('No safe access beside the vehicle.');document.querySelector('dialog').close();walk(p.x,p.z,'Walk to '+VEHICLES[id].name,()=>enter(id));};
 window.exitFarmVehicle=()=>{if(!active)return;const v=ensureVehicles(state).owned[active];if(Math.abs(motion.speed)>.8)return toast('Brake to a stop before getting out.');const p=exitPosition(v,blocked);if(!p)return toast('No safe space to get out. Move to an open spot.');active=null;motion.speed=0;player.visible=true;if(shadow)shadow.visible=true;player.position.set(p.x,.2,p.z);for(const k in keys)keys[k]=false;document.querySelector('dialog').close();hud();save();toast('Parked. Your farmer is on foot.');};
 const parked=id=>{const v=ensureVehicles(state).owned[id];if(!v||!near(v))throw Error('Walk to the vehicle first.');if(active&&Math.abs(motion.speed)>.1)throw Error('Brake to a stop first.');};
 window.chargeFarmVehicle=id=>apply(()=>{parked(id);rechargeVehicle(state,id);},'Battery charged.');
 window.loadFarmVehicle=(id,request)=>apply(()=>{parked(id);loadVehicleContract(state,id,request);},'Cargo loaded. Drive to the delivery depot.');
 window.unloadFarmVehicle=id=>apply(()=>{parked(id);unloadVehicle(state,id);},'Cargo returned to farm stores.');
 window.deliverFarmVehicle=(id,request)=>apply(()=>{parked(id);deliverVehicle(state,id,request);},'Delivery handed over; coins and reputation received.');
 window.recoverFarmVehicle=id=>apply(()=>{if(active&&Math.abs(motion.speed)>.1)throw Error('Stop before requesting recovery.');recoverVehicle(state,id);},'Vehicle recovered to the garage; cargo kept.');
 window.workFarmTractor=()=>{if(active!=='tractor')return;if(Math.abs(motion.speed)>.5)return toast('Stop the tractor before field work.');try{const action=tractorWork(state);working=2;save();toast('North Fields '+action+' with your tractor.');}catch(e){toast(e.message);}};
 window.brakeFarmVehicle=()=>{keys.vehicleBrake=true;};window.releaseFarmBrake=()=>{keys.vehicleBrake=false;};
 window.addEventListener('pagehide',()=>{if(active)save();});
 return {isDriving:driving,actors,tick(dt){sync();if(!active)return;const v=ensureVehicles(state).owned[active],modalOpen=document.querySelector('dialog').open;const throttle=(keys.w||keys.arrowup?1:0)-(keys.s||keys.arrowdown?1:0),steer=(keys.d||keys.arrowright?1:0)-(keys.a||keys.arrowleft?1:0);const result=vehicleStep(v,active,{throttle:modalOpen?0:throttle,steer:modalOpen?0:steer,brake:modalOpen||keys[' ']||keys.vehicleBrake},dt,(x,z)=>blocked(x,z)||Object.entries(state.vehicles.owned).some(([id,o])=>id!==active&&Math.hypot(x-o.x,z-o.z)<VEHICLES[id].radius+1),motion);const actor=actors.get(active);actor.root.position.set(v.x,.2,v.z);actor.root.rotation.y=v.heading;actor.update(result.moved,steer,v.cargo.length>0,working>0);player.position.set(v.x,.2,v.z);player.rotation.y=v.heading;working=Math.max(0,working-dt);saveClock+=dt;hudClock+=dt;if(hudClock>.15){hud();hudClock=0;}if(saveClock>2){save();saveClock=0;}},guard(){if(active){toast('Park and get out before starting a walking task.');return true;}return false;}};
}
